const MODEL = 'gemini-3.5-flash-lite';
const RUN_LABEL = 'Run 3 - with Pinecone RAG';

const NAMES = {
  T1: 'Detailed transcript', T2: 'Vague brief', T3: 'Contradictory',
  T4: 'Feature request with acceptance criteria', T5: 'Incomplete notes',
  T6: 'Multi-stakeholder', T7: 'Technical requirements', T8: 'User persona heavy',
  T9: 'Empty/minimal', T10: 'Feature with dependencies',
  T11: 'PRD generation (from T1)', T12: 'Story breakdown (from T11)'
};
const MANUAL = {
  T3: 'Confirm the contradiction is flagged for stakeholder resolution and neither statement is dropped.',
  T6: 'Confirm all three viewpoints are captured neutrally and no side is favoured.',
  T10: 'Confirm the unknown ETA is flagged as a risk.',
  T11: 'Skim the PRD for any content not in T1.',
  T12: 'Confirm the priorities are sensible.'
};
const STORIES_MARK = '# Epics, Features and User Stories';

const norm = s => String(s == null ? '' : s).replace(/\s+/g, ' ').trim().toLowerCase();
const flatJson = v => norm(JSON.stringify(v == null ? '' : v));

const results = {};
$input.all().forEach(i => { if (i.json && i.json.test_id) results[i.json.test_id] = i.json; });

const allStories = r => {
  const out = [];
  ((r.stories && r.stories.epics) || []).forEach(e =>
    (e.features || []).forEach(f => (f.stories || []).forEach(s => out.push(s))));
  return out;
};

const evaluate = (id, r) => {
  const checks = [];
  const add = (name, ok) => checks.push({ name, ok: !!ok });
  if (!r) { add('workflow returned a result', false); return checks; }

  const ext = r.extraction || {};
  const reqs = ext.stated_requirements || [];
  const src = norm(r.input_text);
  const md = norm(r.markdown);
  const extText = flatJson(ext);
  const gapText = flatJson(r.gaps);
  const all = extText + ' ' + gapText + ' ' + md;

  add('extractor JSON parsed', !r.parse_failed);
  add('every requirement quote found in input', reqs.every(q => src.includes(norm(q.source_quote))));
  add('no sample-PRD content leaked into output', !/bookmark/.test(md));

  switch (id) {
    case 'T1':
      ['date range', 'category', 'status', '2 seconds', 'sarah', 'q3']
        .forEach(k => add(`mentions "${k}"`, all.includes(k)));
      add('PRD generated (status COMPLETE)', r.status === 'COMPLETE');
      add('1 to 4 requirements, none extra', reqs.length >= 1 && reqs.length <= 4);
      break;
    case 'T2':
      add('flagged insufficient or ambiguous', r.status === 'INSUFFICIENT' || (ext.ambiguities || []).length > 0);
      add('no specific requirements invented', reqs.length === 0);
      add('asks about metrics', /metric/.test(all));
      add('asks about format', /format/.test(all));
      add('asks about users', /user|audience|persona/.test(all));
      break;
    case 'T3': {
      const c = flatJson(ext.contradictions);
      add('contradiction recorded', (ext.contradictions || []).length >= 1);
      add('contradiction is refresh vs API calls', /refresh/.test(c) && /api|call|performance/.test(c));
      add('flagged for resolution', /resol|stakeholder/.test(c + ' ' + gapText + ' ' + md));
      break;
    }
    case 'T4': {
      const ac = (ext.acceptance_criteria || []).map(a => norm(a.text));
      add('acceptance criteria extracted verbatim', ac.length > 0 && ac.every(t => src.includes(t)));
      add('PDF logo criterion present', ac.some(t => t.includes('logo')));
      add('CSV formulas criterion present', ac.some(t => t.includes('formula')));
      add('no extra criteria (max 2)', ac.length <= 2);
      const sac = allStories(r).flatMap(s => (s.acceptance_criteria || []).map(norm));
      add('stories carry both criteria', sac.some(t => t.includes('logo')) && sac.some(t => t.includes('formula')));
      add('story criteria all verbatim from input', sac.every(t => src.includes(t)));
      break;
    }
    case 'T5': {
      const m = flatJson(ext.missing_info) + ' ' + gapText;
      add('flagged insufficient', r.status === 'INSUFFICIENT');
      add('no requirements invented', reqs.length === 0);
      add('asks about the dashboard', /dashboard/.test(m));
      add('asks about real-time', /real.?time/.test(m));
      add('asks about the budget', /budget/.test(m));
      add('no PRD generated', !md.includes('## 1. overview'));
      break;
    }
    case 'T6':
      ['engineering', 'microservice', 'design', 'single', 'march']
        .forEach(k => add(`captures "${k}"`, extText.includes(k)));
      add('tension identified', (ext.contradictions || []).length >= 1 || /tension|conflict/.test(all));
      break;
    case 'T7': {
      add('10,000 preserved', extText.includes('10,000'));
      add('200ms at p95 preserved', /200\s?(ms|milliseconds)/.test(extText) && extText.includes('p95'));
      add('Salesforce v52 preserved', extText.includes('salesforce') && extText.includes('v52'));
      const num = reqs.filter(q => /10,000|200\s?(ms|milliseconds)|v52/.test(norm(q.text)));
      add('numeric requirements classified as nfr', num.length >= 2 && num.every(q => q.type === 'nfr'));
      break;
    }
    case 'T8': {
      const pers = flatJson(ext.personas);
      const sp = allStories(r).map(s => norm(s.persona));
      add('Admin persona', /admin/.test(pers));
      add('End User persona', /end.?user/.test(pers));
      add('Auditor persona', /auditor/.test(pers));
      add('separate Admin story', sp.some(p => p.includes('admin')));
      add('separate End User story', sp.some(p => /end.?user/.test(p)));
      add('separate Auditor story', sp.some(p => p.includes('auditor')));
      break;
    }
    case 'T9':
      add('no PRD generated', r.status !== 'COMPLETE' && !md.includes('## 1. overview'));
      add('flagged as no requirements', r.status === 'BLOCKED_BY_GUARD' || r.status === 'INSUFFICIENT');
      break;
    case 'T10': {
      const dep = flatJson(ext.dependencies);
      add('SSO feature extracted', /sso/.test(extText));
      add('auth service dependency flagged', /auth/.test(dep));
      add('Team Alpha identified', dep.includes('team alpha'));
      add('ETA recorded as unknown', (ext.dependencies || []).some(d => norm(d.eta) === 'unknown'));
      add('unknown ETA surfaced as risk or question', /\beta\b/.test(md + ' ' + gapText));
      break;
    }
    case 'T11': {
      const rawPrd = r.prd_markdown || (r.markdown || '').split(STORIES_MARK)[0];
      const prd = norm(String(rawPrd).replace(/\\n/g, '\n'));
      add(`PRD text present (${prd.length} characters)`, prd.length > 200);
      const heads = ['overview', 'goals', 'user personas', 'feature list', 'acceptance criteria',
        'non-functional requirements', 'stakeholders and deadlines', 'dependencies and risks',
        'assumptions', 'open questions'];
      heads.forEach((h, i) => add(
        `has section ${i + 1}. ${h}`,
        new RegExp('#+\\s*' + (i + 1) + '\\.?\\s*' + h.replace(/-/g, '[- ]')).test(prd)
      ));
      add('mentions the T1 requirements', prd.includes('filter') && prd.includes('2 seconds'));
      add('no content from other tests', !/\b(export|pdf|csv|salesforce|sso|dashboard|bookmarks?)\b/.test(prd));
      break;
    }
    case 'T12': {
      const st = allStories(r);
      add('epics and stories produced', ((r.stories && r.stories.epics) || []).length > 0 && st.length > 0);
      add('all stories in "As a ..., I want ..." format',
        st.length > 0 && st.every(s => /^as an? .+,? i want/i.test(String(s.story || ''))));
      add('every story has a valid priority',
        st.length > 0 && st.every(s => ['Must Have', 'Should Have', 'Nice to Have'].includes(s.priority)));
      break;
    }
  }
  return checks;
};

const ids = ['T1','T2','T3','T4','T5','T6','T7','T8','T9','T10','T11','T12'];
const cap = (s, n = 3500) => { s = String(s || ''); return s.length > n ? s.slice(0, n) + '\n...[truncated]' : s; };

const rows = ids.map(id => {
  const derived = id === 'T11' || id === 'T12';
  const r = derived ? results['T1'] : results[id];
  const checks = evaluate(id, r);
  const failed = checks.filter(c => !c.ok).map(c => c.name);
  let output = r ? (r.markdown || '') : 'NO RESULT';
  if (id === 'T11' && r) output = r.prd_markdown || (r.markdown || '').split(STORIES_MARK)[0];
  if (id === 'T12' && r) output = STORIES_MARK + (r.markdown || '').split(STORIES_MARK)[1];
  return {
    test_id: id,
    name: NAMES[id],
    input: derived ? '(derived from T1 output)' : (r ? r.input_text : ''),
    route: r ? r.status : 'NO RESULT',
    result: failed.length ? 'FAIL' : 'PASS',
    checks_passed: `${checks.length - failed.length} of ${checks.length}`,
    failed_checks: failed.join('; '),
    manual_review: MANUAL[id] || '',
    json_repaired: r ? r.json_repaired : '',
    parse_failed: r ? r.parse_failed : '',
    trace_id: r ? r.trace_id : '',
    requirements_found: r && r.extraction ? (r.extraction.stated_requirements || []).map(q => q.text).join(' | ') : '',
    criteria_found: r && r.extraction ? (r.extraction.acceptance_criteria || []).map(a => a.text).join(' | ') : '',
    contradictions_found: r && r.extraction ? (r.extraction.contradictions || []).map(c => `${c.statement_a} <> ${c.statement_b}`).join(' | ') : '',
    output
  };
});

const esc = v => `"${String(v == null ? '' : v).replace(/"/g, '""')}"`;
const cols = ['test_id','name','input','route','result','checks_passed','failed_checks','manual_review','json_repaired','parse_failed','trace_id','requirements_found','criteria_found','contradictions_found'];
const csv = [cols.join(',')].concat(rows.map(r => cols.map(c => esc(r[c])).join(','))).join('\n');

const passed = rows.filter(r => r.result === 'PASS').length;
let report = `# PRD Genie baseline test results\n\n${RUN_LABEL}\nRun date: ${new Date().toISOString()}\nModel: ${MODEL}\nPassed: ${passed} / ${rows.length}\n\n`;
report += '| Test | Name | Route | Result | Checks | Failed checks |\n|---|---|---|---|---|---|\n';
rows.forEach(r => {
  report += `| ${r.test_id} | ${r.name} | ${r.route} | ${r.result} | ${r.checks_passed} | ${r.failed_checks || '-'} |\n`;
});
report += '\nAutomated checks are keyword and structure tests. Items under "Manual review" need a human look.\n';
rows.forEach(r => {
  report += `\n---\n\n## ${r.test_id}: ${r.name}: ${r.result}\n\n`;
  report += `**Input:** ${r.input}\n\n**Route:** ${r.route}  |  **Checks passed:** ${r.checks_passed}  |  **JSON repaired:** ${r.json_repaired}\n\n`;
  if (r.requirements_found) report += `**Requirements extracted:** ${r.requirements_found}\n\n`;
  if (r.criteria_found) report += `**Acceptance criteria extracted:** ${r.criteria_found}\n\n`;
  if (r.contradictions_found) report += `**Contradictions recorded:** ${r.contradictions_found}\n\n`;
  if (r.failed_checks) report += `**Failed checks:** ${r.failed_checks}\n\n`;
  if (r.manual_review) report += `**Manual review:** ${r.manual_review}\n\n`;
  report += `**Output:**\n\n~~~markdown\n${cap(r.output)}\n~~~\n`;
});

return [{ json: { passed, total: rows.length, csv, report_md: report, rows } }];
